package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var currRec DateRec
var scanner *bufio.Scanner

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func truncStore(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	pow := int64(1)
	for i := 0; i < digits; i++ {
		pow *= 10
	}
	if val >= 0 {
		return val % pow
	}
	return -((-val) % pow)
}

func formatNum(val int64, width int) string {
	v := truncStore(val, width)
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%0*d", width, v)
}

func parseNum(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	scanner = bufio.NewScanner(f)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n", formatNum(WsValid, 2), formatNum(WsBadMonth, 2), formatNum(WsBadDay, 2))
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		currRec.DtId = line[0:4]
		currRec.DtYyyy = parseNum(line[4:8])
		currRec.DtMm = parseNum(line[8:10])
		currRec.DtDd = parseNum(line[10:12])
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	LeapPara()
	if currRec.DtMm < 1 || currRec.DtMm > 12 {
		WsBadMonth = truncStore(WsBadMonth+1, 2)
		fmt.Printf("%s BAD MONTH %s\n", currRec.DtId, formatNum(currRec.DtMm, 2))
	} else {
		DaysPara()
		if currRec.DtDd < 1 || currRec.DtDd > WsMaxDay {
			WsBadDay = truncStore(WsBadDay+1, 2)
			fmt.Printf("%s BAD DAY %s MAX %s\n", currRec.DtId, formatNum(currRec.DtDd, 2), formatNum(WsMaxDay, 2))
		} else {
			WsValid = truncStore(WsValid+1, 2)
			fmt.Printf("%s VALID %s-%s-%s\n", currRec.DtId, formatNum(currRec.DtYyyy, 4), formatNum(currRec.DtMm, 2), formatNum(currRec.DtDd, 2))
		}
	}
	ReadPara()
}

func LeapPara() {
	WsQ = truncStore(currRec.DtYyyy/4, 4)
	WsR4 = truncStore(currRec.DtYyyy%4, 3)
	WsQ = truncStore(currRec.DtYyyy/100, 4)
	WsR100 = truncStore(currRec.DtYyyy%100, 3)
	WsQ = truncStore(currRec.DtYyyy/400, 4)
	WsR400 = truncStore(currRec.DtYyyy%400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch currRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	WsMaxDay = truncStore(WsMaxDay, 2)
}

func main() {
	MainPara()
}
